  var DEFAULTS = { target: 75, theme: "system", amoled: false };
  var listeners = /* @__PURE__ */ new Set();
  var prefs = {
    get(k) {
      try {
        const v = JSON.parse(localStorage.getItem("jp:pref:" + k));
        return v ?? DEFAULTS[k];
      } catch {
        return DEFAULTS[k];
      }
    },
    set(k, v) {
      try {
        localStorage.setItem("jp:pref:" + k, JSON.stringify(v));
      } catch {
      }
      listeners.forEach((f) => f(k, v));
    },
    onChange(f) {
      listeners.add(f);
      return () => listeners.delete(f);
    }
  };

