  function icon(name, size = 24, extra = {}) {
    const ic = ICONS[name];
    if (!ic) return h("span", { style: { width: size + "px", height: size + "px", display: "inline-block" } });
    return h(
      "svg",
      { viewBox: ic.vb, width: size, height: size, fill: "currentColor", "aria-hidden": "true", ...extra },
      ic.d.map((d) => h("path", { d }))
    );
  }

